#include <stdio.h>

int main() {
    FILE *file;
    int data = 12345;

    // Writing to a binary file
    file = fopen("data.bin", "wb");
    if (file) {
        fwrite(&data, sizeof(int), 1, file);
        fclose(file);
    }

    // Reading from a binary file
    file = fopen("data.bin", "rb");
    if (file) {
        fread(&data, sizeof(int), 1, file);
        fclose(file);
        printf("Data: %d\n", data);
    }

    return 0;
}
